static Json bunch(int channel,int seq,const Bits& payload,bool reliable=true){return {{"channel",channel},{"channel_name",102},{"reliable",reliable},{"reliable_sequence",seq&1023},{"payload_hex",hex(payload.data)},{"payload_bits",payload.bits}};}static Json creation(int initial,int channel,Guid actor,Ref archetype,std::optional<Vec> location,bool controller){Ref level=level_ref();Bits ex=exports({archetype,level});BitWriter w;actor.write(w);archetype.guid.write(w);level.guid.write(w);if(location){w.write(1,1).write(1,1);std::array<int64_t,3>a;int n=1;for(int i=0;i<3;i++){a[i]=int64_t(std::floor(std::abs((*location)[i])*10+.5))*((*location)[i]<0?-1:1);uint64_t t=uint64_t(std::abs(a[i]));int k=1;while(t){k++;t>>=1;}n=std::max(n,k);}require(n<=63,"Spawn range");w.write(n|64,7);for(auto v:a)w.write(uint64_t(v)&((1ULL<<n)-1),n);}else w.write(0,1);w.write(0,3);if(controller)w.write(0,8);Json first=bunch(channel,initial+1,ex),last=bunch(channel,initial+2,{w.data,w.bits});first["partial"]=last["partial"]=true;first["open"]=true;first["exports"]=true;first["partial_flags"]={1,0,0};last["partial_flags"]={0,0,1};return Json::array({first,last});}
