auto it=connections.find(peer);if(it==connections.end())return {};auto& c=it->second;c.last_seen=now;if(c.session!=p["session_id"]||c.client!=p["client_id"])return {};if(c.phase=="closed")return {send(c)};int delta=(p.at("sequence").get<int>()-c.in_seq)&16383;if(delta==0)return {send(c)};if(delta>=8192)return {};for(auto a=c.pending.begin();a!=c.pending.end();){unsigned distance=(p.at("ack").get<int>()-a->first)&16383;auto& h=p.at("ack_history");if(distance<h.size()*32&&(h[distance/32].get<uint32_t>()>>(distance%32)&1)){c.pending_at.erase(a->first);a=c.pending.erase(a);}else ++a;}c.in_seq=p["sequence"];c.history<<=std::min(delta,256);c.history.set(0);c.info=p.at("custom_header_opaque").get<uint64_t>();std::vector<Bytes> out;
for(auto& b:p["bunches"]){if(b["channel"]!=0||!b.contains("messages"))continue;if(b["reliable"]==true){int seq=b["reliable_sequence"];int expected=(c.in_reliable+1)&1023;int backwards=(c.in_reliable-seq)&1023;if(backwards<512)continue;if(seq!=expected){c.history.reset(0);continue;}c.in_reliable=seq;}if(b["close"]==true){c.phase="closed";c.pending.clear();event("udp_connection_closed",{{"connection_id",c.id}});continue;}for(auto& m:b["messages"]){int id=m["id"];std::optional<Bytes> reply;if(id==0&&c.phase=="connected"){c.phase="challenged";reply=encode_control(3,{{"text",random_id(8)}});}else if(id==5&&(c.phase=="challenged"||c.phase=="connected")){c.phase="welcomed";reply=encode_control(1,{{"map","/Game/Levels/Verra_World_Master/Verra_World_Master"},{"game_mode","/Game/GameBlueprints/AoCGameModeBaseBP.AoCGameModeBaseBP_C"}});event("welcome",{{"connection_id",c.id}});}else if(id==9&&c.phase=="welcomed"){c.phase="joined";event("join",{{"connection_id",c.id},{"peer",peer}});}if(reply){c.out_reliable=(c.out_reliable+1)&1023;Json bs=Json::array({{{"channel",0},{"channel_name",255},{"reliable",true},{"reliable_sequence",c.out_reliable},{"payload_hex",hex(*reply)}}});out.push_back(send(c,bs));}}}
